// Builds db/supabase-setup.sql: every migration in order, in ONE file you can paste into the Supabase SQL Editor.
//   npm run db:bundle
import { readdirSync, readFileSync, writeFileSync } from 'node:fs'
import path from 'node:path'

const root = path.resolve(import.meta.dirname, '..')
const dir = path.join(root, 'db/migrations')
const files = readdirSync(dir).filter((f) => f.endsWith('.sql')).sort()

let out = `-- StoryChurch Auction — complete database setup for a NEW, EMPTY Supabase project.
-- Generated by \`npm run db:bundle\` from db/migrations/*.sql. Run it ONCE:
--   Supabase dashboard → SQL Editor → New query → paste this whole file → Run.
-- It creates the tables, protections, and turns on row-level security everywhere
-- (the public API key can read or write nothing; only the server can).
-- It creates NO demo data.

create table if not exists schema_migrations (name text primary key, applied_at timestamptz not null default now());
alter table schema_migrations enable row level security;

`
for (const f of files) {
  out += `-- ════════════ ${f} ════════════\n${readFileSync(path.join(dir, f), 'utf8').trim()}\n\n`
  out += `insert into schema_migrations (name) values ('${f}') on conflict do nothing;\n\n`
}
writeFileSync(path.join(root, 'db/supabase-setup.sql'), out)
console.log(`wrote db/supabase-setup.sql (${files.length} migrations, ${out.split('\n').length} lines)`)
